arguments.file_text:
@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <nav class="settings-sidebar">
        <h2 class="settings-title">Settings</h2>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(section == _activeSection ? "active" : "")"
                    @onclick="() => _activeSection = section">
                    <span class="nav-icon">@GetIcon(section)</span>
                    <span>@section</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSettings />
                break;
            case "Notifications":
                <NotificationSettings />
                break;
            case "Security":
                <SecuritySettingsPanel />
                break;
            case "Appearance":
                <AppearanceSettings />
                break;
        }
    </main>
</div>

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-layout {
    display: grid;
    grid-template-columns: 240px 1fr;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-sidebar {
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
}

.settings-title {
    font-size: 1.25rem;
    font-weight: 600;
    padding: 0 1.5rem;
    margin-bottom: 1rem;
    color: #1a1a1a;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    color: #555;
    font-weight: 500;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.settings-nav li:hover {
    background: #eef1f5;
    color: #1a1a1a;
}

.settings-nav li.active {
    background: #e8f0fe;
    color: #1a73e8;
    border-left-color: #1a73e8;
}

.nav-icon {
    font-size: 1.1rem;
}

.settings-content {
    padding: 2rem 3rem;
    max-width: 800px;
}

