arguments.file_text:
@inject ISettingsService SettingsService

<section class="notification-settings">
    <h3>Notifications</h3>

    @if (_loading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <div class="toggle-item">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <span class="toggle-desc">Receive updates via email</span>
                </label>
                <label class="switch">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="slider"></span>
                </label>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <span class="toggle-desc">Receive push notifications in your browser</span>
                </label>
                <label class="switch">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="slider"></span>
                </label>
            </div>

            <div class="toggle-item">
                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <span class="toggle-desc">Get a summary of activity each week</span>
                </label>
                <label class="switch">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="slider"></span>
                </label>
            </div>
        </div>

        <div class="channels-section">
            <h4>Muted Channels</h4>
            <p class="channels-desc">Select channels you want to mute:</p>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        <span>@channel</span>
                    </label>
                }
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">✓ Notification preferences saved!</div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();

    private readonly string[] _allChannels = ["General", "Announcements", "Engineering", "Design", "Marketing", "Support"];

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.notification-settings h3 {
    font-size: 1.5rem;
    margin-bottom: 1.5rem;
    color: #1a1a1a;
}

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 0;
    border-bottom: 1px solid #eee;
}

.toggle-label {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
}

.toggle-label span:first-child {
    font-weight: 500;
    color: #1a1a1a;
}

.toggle-desc {
    font-size: 0.85rem;
    color: #666;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #ccc;
    transition: 0.2s;
