arguments.file_text:
@inject ISettingsService SettingsService

<section class="appearance-settings">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="setting-section">
            <h4>Theme</h4>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-item @(_theme == theme ? "selected" : "")">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span class="radio-label">@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="setting-section">
            <h4>Font Size</h4>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-item @(_fontSize == size ? "selected" : "")">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span class="radio-label">@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="setting-section">
            <h4>Language</h4>
            <select class="language-select" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="setting-section">
            <div class="toggle-item">
                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <span class="toggle-desc">Reduce spacing and padding throughout the UI</span>
                </label>
                <label class="switch">
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="slider"></span>
                </label>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="setting-section">
            <h4>Preview</h4>
            <div class="preview-area @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">
                    This is how your content will look with the selected appearance settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <div class="preview-buttons">
                    <button class="preview-btn-primary">Primary Action</button>
                    <button class="preview-btn-secondary">Secondary</button>
                </div>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">✓ Appearance settings saved!</div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Korean", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);

        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.appearance-settings h3 {
    font-size: 1.5rem;
    margin-bottom: 1.5rem;
    color: #1a1a1a;
}

.setting-section {
    margin-bottom: 1.75rem;
}

.setting-section h4 {
    font-size: 1rem;
    margin-bottom: 0.75rem;
    color: #333;
}

.radio-group {
    display: flex;
    gap: 0.5rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s;
}

.radio-item:hover {
    border-color: #1a73e8;
}

.radio-item.selected {
    border-color: #1a73e8;
    background: #e8f0fe;
}

.radio-item input[type="radio"] {
    accent-color: #1a73e8;
}

.radio-label {
    font-weight: 500;
    font-size: 0.9rem;
}

.language-select {
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    min-width: 200px;
    background: white;
}

.language-select:focus {
    outline: none;
    border-color: #1a73e8;
    box-shadow: 0 0 0 2px rgba(26, 115, 232, 0.15);
}

.toggle-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.toggle-label {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
}

.toggle-label span:first-child {
    font-weight: 500;
    color: #1a1a1a;
}

.toggle-desc {
    font-size: 0.85rem;
    color: #666;
}

.switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #ccc;
    transition: 0.2s;
    border-radius: 24px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.2s;
    border-radius: 50%;
}

input:checked + .slider {
    background-color: #1a73e8;
}

input:checked + .slider::before {
    transform: translateX(20px);
}

/* Live Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    transition: all 0.2s ease;
}

.preview-area.theme-light {
    background: #ffffff;
    color: #1a1a1a;
}

.preview-area.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-system {
    background: #f8f9fa;
    color: #1a1a1a;
}

.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 0.95rem;
}

.preview-area.font-large {
    font-size: 1.15rem;
}

.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 600;
    font-size: 1.15em;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 1rem;
    opacity: 0.85;
    line-height: 1.5;
}

.preview-buttons {
    display: flex;
    gap: 0.5rem;
}

.preview-btn-primary {
    padding: 0.4rem 0.9rem;
    background: #1a73e8;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 0.85em;
}

.preview-btn-secondary {
    padding: 0.4rem 0.9rem;
    background: transparent;
    border: 1px solid currentColor;
    border-radius: 4px;
    color: inherit;
    font-size: 0.85em;
    opacity: 0.7;
}

.button-group {
    margin-top: 1.5rem;
}

.btn-primary {
    background: #1a73e8;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    font-weight: 500;
    cursor: pointer;
}

.btn-primary:hover:not(:disabled) {
    background: #1557b0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
}

.toast.success {
    background: #e6f4ea;
    color: #1e7e34;
    border: 1px solid #b7e1c4;
}

.loading {
    color: #666;
    font-style: italic;
}

@inject ISettingsService SettingsService

<section class="appearance-settings">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="setting-section">
            <h4>Theme</h4>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-item @(_theme == theme ? "selected" : "")">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span class="radio-label">@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="setting-section">
            <h4>Font Size</h4>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-item @(_fontSize == size ? "selected" : "")">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span class="radio-label">@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="setting-section">
            <h4>Language</h4>
            <select class="language-select" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="setting-section">
            <div class="toggle-item">
                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <span class="toggle-desc">Reduce spacing and padding throughout the UI</span>
                </label>
                <label class="switch">
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="slider"></span>
                </label>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="setting-section">
            <h4>Preview</h4>
            <div class="preview-area @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">
                    This is how your content will look with the selected appearance settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <div class="preview-buttons">
                    <button class="preview-btn-primary">Primary Action</button>
                    <button class="preview-btn-secondary">Secondary</button>
                </div>
            </div>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save")
            </button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">✓ Appearance settings saved!</div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Korean", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;

        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);

        _saving = false;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

